package com.agacostays.billing.service.impl;
import com.agacostays.billing.dto.response.BillCalculationResponse;import com.agacostays.billing.entity.TaxConfiguration;import com.agacostays.billing.repository.TaxConfigurationRepository;import com.agacostays.billing.service.BillCalculationService;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.math.*;
@Service public class BillCalculationServiceImpl implements BillCalculationService{private final TaxConfigurationRepository tr;private final BigDecimal def;private final String cur;public BillCalculationServiceImpl(TaxConfigurationRepository t,@Value("${billing.default-tax-rate}")BigDecimal d,@Value("${billing.currency}")String c){tr=t;def=d;cur=c;}public BillCalculationResponse calculate(BigDecimal r,BigDecimal f,BigDecimal d,Long branch){r=n(r);f=n(f);d=n(d);BigDecimal sub=r.add(f),taxable=sub.subtract(d).max(BigDecimal.ZERO);BigDecimal rate=tr.findByBranchIdAndActiveTrue(branch).map(TaxConfiguration::getTaxRate).orElse(def);BigDecimal tax=taxable.multiply(rate).setScale(2,RoundingMode.HALF_UP);return new BillCalculationResponse(sub,tax,d,taxable.add(tax).setScale(2,RoundingMode.HALF_UP),cur);}private BigDecimal n(BigDecimal x){return x==null?BigDecimal.ZERO.setScale(2):x.setScale(2,RoundingMode.HALF_UP);}}
